function partitionArray(nums, k) {
  let best = nums.length;
  const lows = [];
  const highs = [];
  const place = (i) => {
    if (lows.length >= best) return;
    if (i === nums.length) { best = lows.length; return; }
    const v = nums[i];
    for (let g = 0; g < lows.length; g++) {
      const lo = Math.min(lows[g], v);
      const hi = Math.max(highs[g], v);
      if (hi - lo > k) continue;
      const oldLo = lows[g];
      const oldHi = highs[g];
      lows[g] = lo;
      highs[g] = hi;
      place(i + 1);
      lows[g] = oldLo;
      highs[g] = oldHi;
    }
    lows.push(v);
    highs.push(v);
    place(i + 1);
    lows.pop();
    highs.pop();
  };
  place(0);
  return best;
}

