function generate(rand, size) {
  const small = size === 'small';
  const n = small ? 1 + Math.floor(rand() * 8) : 2000;
  const top = small ? [3, 12, 100000][Math.floor(rand() * 3)] : [100, 100000][Math.floor(rand() * 2)];
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const kChoice = rand();
  let k;
  if (kChoice < 0.2) k = 0;
  else if (kChoice < 0.3) k = 100000;
  else k = Math.floor(rand() * (small ? Math.min(top, 12) + 1 : (top >> 3) + 1));
  return [nums, k];
}
